import { Injectable } from '@angular/core';
import { TostbarService } from '../../../core/services/tost/tostbar.service';
import { HttpClient, HttpParams } from '@angular/common/http';
import { SecureStorageService } from '../../../core/services/storage/secure-storage.service';
import { firstValueFrom } from 'rxjs';
import { environment } from '../../../../environments/environment';
import { indexResponce } from '../../interfaces/indexing.interface';

@Injectable({
  providedIn: 'root'
})
export class IndexingService {

  constructor(public sStore: SecureStorageService, private http: HttpClient, public tost: TostbarService) { }

  async generateIndexing(nCaseid: string, cFilename: string, nSectionid: string, cHyperlinktype: string, isCoverpg: boolean, isIndexpg: boolean, column: any): Promise<boolean> {
    try {
      const params = { nCaseid: nCaseid, nSectionid: nSectionid, cFilename: cFilename, cHyperlinktype: cHyperlinktype, column: column, bCoverpg: isCoverpg, bIndexpg: isIndexpg };
      let res: indexResponce = await firstValueFrom(
        this.http.post<any>(
          `${environment.indexservice}/generateindex/indexdata`,
          params
        )
      );
      if (res && res.msg == 1) {
        // this.tost.openSnackBar(res.value, '');
        return true;
      } else {
        // this.tost.openSnackBar(res.value, 'E');
        return false;
      }
    } catch (err) {
      console.error(err)
      return false;
    }

  }


}
